using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly List<(string Method, string Path, string? ContentType, string Body)> received = [];
    private int statusCode = 200;
    private string responseBody = """{"status":"approved"}""";

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(prefix) };
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_as_json()
    {
        await Gateway().AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        var call = Assert.Single(received);
        Assert.Equal("POST", call.Method);
        Assert.Equal("/v1/authorizations", call.Path);
        Assert.StartsWith("application/json", call.ContentType);
        using var json = JsonDocument.Parse(call.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_with_extra_fields_is_still_read()
    {
        responseBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline_not_an_error()
    {
        statusCode = 402;
        responseBody = """{"error":"card_refused"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_raised_rather_than_treated_as_declines(int status)
    {
        statusCode = status;
        responseBody = """{"status":"approved"}""";

        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_approval_is_never_read_as_approved(string body)
    {
        responseBody = body;

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_raised()
    {
        responseBody = "<html>gateway error</html>";

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    private HttpPaymentGateway Gateway() => new(client);

    private Task<AuthorizationOutcome> Authorize() =>
        Gateway().AuthorizeAsync("ORD-7", new Money(10m, "EUR"), CancellationToken.None);

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch { return; }

            using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            var body = await reader.ReadToEndAsync();
            lock (received)
                received.Add((context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, body));

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = statusCode;
            context.Response.ContentType = "application/json";
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private static int FreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
